function renderPeerStatus(){const el=$("#peer-status");if(!el)return;if(!activeConversation)return;if(activeConversation.kind==="group"){el.textContent="Group conversation";el.classList.remove("is-online","is-typing");return}const online=Boolean(activePeer?.is_online);el.classList.toggle("is-online",online);el.classList.toggle("is-typing",Boolean(el.dataset.typing==="true"));if(el.dataset.typing==="true")el.textContent="typing…";else if(online)el.textContent="online";else if(activePeer?.last_seen)el.textContent="last seen "+niceTime(activePeer.last_seen);else el.textContent="offline"}
function subscribeToPeerPresence(){if(peerPresenceChannel){activeClient.removeChannel(peerPresenceChannel);peerPresenceChannel=null}if(typingChannel){activeClient.removeChannel(typingChannel);typingChannel=null}if(!activeConversation||!activeUser)return;const conversationId=activeConversation.id;peerPresenceChannel=activeClient.channel("zc-peer-profile-"+conversationId+"-"+activeUser.id).on("postgres_changes",{event:"UPDATE",schema:"public",table:"profiles",filter:"id=eq."+String(activePeer?.id||"00000000-0000-0000-0000-000000000000")},payload=>{if(!payload.new)return;activePeer={...(activePeer||{}),...payload.new};renderPeerStatus();if(payload.new.avatar_url!==undefined){setProfileAvatar($("#peer-avatar"),activePeer,profileName(activePeer));setProfileAvatar($("#info-avatar"),activePeer,profileName(activePeer))}}).subscribe(status=>{if(status==="CHANNEL_ERROR"||status==="TIMED_OUT")console.warn("Peer presence realtime unavailable",status)});typingChannel=activeClient.channel("zc-typing-"+conversationId,{config:{broadcast:{self:false}}}).on("broadcast",{event:"typing"},({payload})=>{if(!payload||payload.user_id===activeUser.id)return;if(typingExpiryTimer)clearTimeout(typingExpiryTimer);const el=$("#peer-status");if(payload.typing){if(el){el.dataset.typing="true";renderPeerStatus()}typingExpiryTimer=setTimeout(()=>{if(el)el.dataset.typing="false";renderPeerStatus()},3500)}else{if(el)el.dataset.typing="false";renderPeerStatus()}}).subscribe(status=>{if(status==="SUBSCRIBED")console.debug("Typing indicator ready")})}
